import { db } from "@/lib/db";

export async function POST(request: Request) {
  const body = await request.json();
  const { title, feedGrams } = body;

  if (!title || !feedGrams) {
    return new Response("Missing or invalid title or feedGrams", { status: 400 });
  }

  if (feedGrams < 1 || feedGrams > 600) {
    return new Response("Invalid feedGrams", { status: 400 });
  }

  const existing = await db.aquariumFeedLog.findUnique({
    where: {
      title,
    },
  });

  if (existing) {
    return new Response("Duplicate title", { status: 409 });
  }

  const newLog = await db.aquariumFeedLog.create({
    data: {
      title,
      feedGrams,
    },
  });

  return new Response(JSON.stringify(newLog), { status: 201 });
}

